function getCollectiveWithShare(int $id, string $userId, ?string $shareToken = null): Collective {
		$collective = $this->getCollective($id, $userId);
		if ($shareToken && null !== $share = $this->shareService->findShareByToken($shareToken)) {
			if ($collective->getId() === $share->getCollectiveId()) {
				$collective->setShareToken($share->getToken());
				$collective->setIsPageShare($share->getPageId() !== 0);
				$collective->setSharePageId($share->getPageId());
				$collective->setShareEditable($share->getEditable());
			} else {
				throw new NotFoundException('Share token does not match collective.');
			}
		}

		return $collective;
	}

function getCollective(int $id, string $userId): Collective {
		if (null === $collective = $this->collectiveMapper->findByIdAndUser($id, $userId)) {
			throw new NotFoundException('Collective not found: ' . $id);
		}
		$collective->setName($this->collectiveMapper->circleIdToName($collective->getCircleId(), $userId));
		$collective->setLevel($this->circleHelper->getLevel($collective->getCircleId(), $userId));

		return $collective;
	}

methods.OCA\\Collectives\\Service\\CollectiveSha:
function findShareByToken(string $token, bool $getPermissionInfo = true): ?CollectiveShare {
		try {
			$collectiveShare = $this->collectiveShareMapper->findOneByToken($token);
		} catch (DoesNotExistException|MultipleObjectsReturnedException|Exception) {
			return null;
		}

		if (!$getPermissionInfo) {
			return $collectiveShare;
		}

		try {
			$folderShare = $this->shareManager->getShareByToken($collectiveShare->getToken());
		} catch (ShareNotFound) {
			// Corresponding folder share not found, delete the collective share as well.
			$this->collectiveShareMapper->delete($collectiveShare);
			return null;
		}

		$collectiveShare->setEditable($this->isShareEditable($folderShare));
		if ($folderShare->getPassword()) {
			$collectiveShare->setPassword($folderShare->getPassword());
		}
		return $collectiveShare;
	}

function isShareEditable(IShare $folderShare): bool {
		$folderShare->getPermissions();
		return ($folderShare->getPermissions() & Collective::editPermissions) === Collective::editPermissions;
	}

methods.OCA\\Collectives\\Service\\PageService:::
function find(int $collectiveId, int $id, string $userId): PageInfo {
		$folder = $this->getCollectiveFolder($collectiveId, $userId);
		return $this->getPageByFile($this->nodeHelper->getFileById($folder, $id));
	}

function getCollective(int $collectiveId, string $userId): Collective {
		if ($this->collective === null || $this->collective->getId() !== $collectiveId) {
			$this->collective = $this->collectiveService->getCollective($collectiveId, $userId);
		}

		return $this->collective;
	}

function getCollectiveFolder(int $collectiveId, string $userId): Folder {
		$collectiveName = $this->getCollective($collectiveId, $userId)->getName();
		$folder = $this->userFolderHelper->get($userId)->get($collectiveName);

		if (!($folder instanceof Folder)) {
			throw new FilesNotFoundException('Folder not found for collective ' . $collectiveId);
		}

		return $folder;
	}

function getFolder(int $collectiveId, int $fileId, string $userId): Folder {
		$collectiveFolder = $this->getCollectiveFolder($collectiveId, $userId);
		if ($fileId === 0) {
			return $collectiveFolder;
		}

		$file = $this->nodeHelper->getFileById($collectiveFolder, $fileId);
		if (!($file->getParent() instanceof Folder)) {
			throw new NotFoundException('Error getting parent folder for file ' . $fileId . ' in collective ' . $collectiveId);
		}

		return $file->getParent();
	}

function getIndexPageFile(Folder $folder): File {
		try {
			$file = $folder->get(PageInfo::INDEX_PAGE_TITLE . PageInfo::SUFFIX);
		} catch (FilesNotFoundException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		}

		if (!($file instanceof File)) {
			throw new NotFoundException('Failed to get index page');
		}

		return $file;
	}

function getPageByFile(File $file, ?Node $parent = null): PageInfo {
		try {
			$page = $this->pageMapper->findByFileId($file->getId());
		} catch (InvalidPathException|FilesNotFoundException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		}
		$lastUserId = ($page !== null) ? $page->getLastUserId() : null;
		$emoji = ($page !== null) ? $page->getEmoji() : null;
		$subpageOrder = ($page !== null) ? $page->getSubpageOrder() : null;
		$fullWidth = $page !== null && $page->getFullWidth();
		$slug = ($page !== null) ? $page->getSlug() : null;
		$tags = ($page !== null) ? $page->getTags() : null;
		$linkedPageIds = ($page !== null) ? $this->pageLinkMapper->findByPageId($page->getFileId()) : null;
		$pageInfo = new PageInfo();
		try {
			$pageInfo->fromFile($file,
				$this->getParentPageId($file, $parent),
				$lastUserId,
				$lastUserId ? $this->userManager->getDisplayName($lastUserId) : null,
				$emoji,
				$subpageOrder,
				$fullWidth,
				$slug,
				$tags,
				$linkedPageIds);
		} catch (FilesNotFoundException|InvalidPathException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		}

		return $pageInfo;
	}

function getParentPageId(File $file, ?Node $parent = null): int {
		try {
			if (NodeHelper::isLandingPage($file)) {
				// Return `0` for landing page
				return 0;
			}

			$parent ??= $file->getParent();

			if (NodeHelper::isIndexPage($file)) {
				// Go down two levels if index page but not landing page
				return self::getIndexPageFile($parent->getParent())->getId();
			}

			return self::getIndexPageFile($parent)->getId();
		} catch (InvalidPathException|FilesNotFoundException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		}
	}

function isPageInPageFolder(int $collectiveId, int $parentId, int $pageId, string $userId): void {
		$folder = $this->getFolder($collectiveId, $parentId, $userId);
		if ($folder->getFirstNodeById($pageId) === null) {
			throw new NotFoundException('Page ' . $pageId . ' is not a child of ' . $parentId);
		}
	}

methods.OCA\\Collectives\\Service\\SearchService:
function areDependenciesMet(): bool {
		return in_array('sqlite', PDO::getAvailableDrivers(), true);
	}

function createFileSearcher(): FileSearcher {
		$defaultLanguage = $this->config->getSystemValue('default_language', 'en');
		return new FileSearcher(FileSearcher::SUPPORTED_LANGUAGES[$defaultLanguage] ?? null);
	}

function getIndexForCollective(Collective $collective): ?File {
		try {
			$file = $this->getIndicesFolder()->get($this->getIndexName($collective));
		} catch (NotFoundException) {
			return null;
		}

		return $file instanceof File ? $file : null;
	}

function getIndicesFolder(): Folder {
		$rootFolder = $this->collectiveFolderManager->getRootFolder();
		try {
			$folder = $rootFolder->get(self::INDICES_DIR_NAME);
			if ($folder instanceof Folder) {
				return $folder;
			}
		} catch (NotFoundException) {
		}

		try {
			return $rootFolder->newFolder(self::INDICES_DIR_NAME);
		} catch (NotPermittedException) {
			throw new FileSearchException('Could not find or create the indices directory.');
		}
	}

function searchCollective(Collective $collective, string $term, int $maxResults = 15): array {
		if (!$this->areDependenciesMet()) {
			$this->logger->warning('Collectives full-text search is not operational, because the PDO SQLite driver is not available.');
			return [];
		}

		$searcher = $this->createFileSearcher();
		$file = $this->getIndexForCollective($collective);
		if ($file === null) {
			$this->logger->warning('Collectives search failed to find search index for collective with ID ' . $collective->getId());
			return [];
		}

		$searcher->selectIndexFile($file);
		return $searcher->search($term, $maxResults);
	}

