methods.OCA\\Collectives\\Service\\CircleHelper::
function getCircle(string $circleId, ?string $userId = null, bool $super = false): Circle {
		try {
			if ($super) {
				$this->startSuperSession();
			} else {
				$this->startSession($userId);
			}
			/** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
			$circle = $this->circlesManager->getCircle($circleId);
		} catch (CircleNotFoundException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		} catch (RequestBuilderException|
				 FederatedItemException $e) {
				 	throw new NotPermittedException($e->getMessage(), 0, $e);
				 }
		$this->circlesManager->stopSession();

		return $circle;
	}

function getCircles(?string $userId = null): array {
		try {
			$this->startSession($userId);
			$circleProbe = new CircleProbe();
			$circleProbe->mustBeMember();
			$dataProbe = new DataProbe();
			$dataProbe->add(DataProbe::INITIATOR);
			/** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
			$circles = self::useProbeCircles()
				? $this->circlesManager->probeCircles($circleProbe, $dataProbe)
				: $this->circlesManager->getCircles($circleProbe, true);
		} catch (RequestBuilderException|
				 FederatedItemException $e) {
				 	throw new NotPermittedException($e->getMessage(), 0, $e);
				 }
		$this->circlesManager->stopSession();

		return $circles;
	}

function getFederatedUser(?string $userId = null): ?FederatedUser {
		if ($userId === null) {
			return null;
		}

		try {
			/** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
			return $this->circlesManager->getFederatedUser($userId, Member::TYPE_USER);
		} catch (CircleNotFoundException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		} catch (FederatedItemException|
				 RequestBuilderException $e) {
				 	throw new NotPermittedException($e->getMessage(), 0, $e);
				 }
	}

function getLevel(string $circleId, string $userId): int {
		if (is_null($this->circlesManager)) {
			throw new MissingDependencyException($this->dependencyInjectionError);
		}

		try {
			$this->startSession($userId);
			$circle = $this->circlesManager->getCircle($circleId);
			$member = $circle->getInitiator();
		} catch (CircleNotFoundException $e) {
			throw new NotFoundException($e->getMessage(), 0, $e);
		} catch (RequestBuilderException|FederatedItemException $e) {
			throw new NotPermittedException($e->getMessage(), 0, $e);
		}

		return $member->getLevel();
	}

function hasLevel(string $circleId, string $userId, int $level = Member::LEVEL_MEMBER): bool {
		return $this->getLevel($circleId, $userId) >= $level;
	}

function startSession(?string $userId = null): void {
		if (is_null($this->circlesManager)) {
			throw new MissingDependencyException($this->dependencyInjectionError);
		}
		$federatedUser = $this->getFederatedUser($userId);
		$this->circlesManager->startSession($federatedUser);
	}

function startSuperSession(): void {
		if (is_null($this->circlesManager)) {
			throw new MissingDependencyException($this->dependencyInjectionError);
		}
		$this->circlesManager->startSuperSession();
	}

function useProbeCircles(): bool {
		[$major, $minor, $micro] = Util::getVersion();
		$version = $major . '.' . $minor . '.' . $micro;
		return $major >= 31
			|| ($major === 30 && version_compare($version, '30.0.3', '>='));
	}

methods.OCA\\Collectives\\Service\\CollectiveHel:
function getCollectivesForUser(string $userId, bool $getLevel = true, bool $getUserSettings = true): array {
		$circles = $this->circleHelper->getCircles($userId);
		$cids = array_map(static fn ($circle) => $circle->getSingleId(), $circles);
		$circles = array_combine($cids, $circles);
		/** @var Collective[] $collectives */
		$collectives = $this->collectiveMapper->findByCircleIds($cids);
		foreach ($collectives as $c) {
			$cid = $c->getCircleId();
			$circle = $circles[$cid];
			$c->setName($circle->getSanitizedName());
			try {
				$c->setLevel($getLevel ? $circle->getInitiator()->getLevel(): 0);
			} catch (\Exception $e) {
				throw new CircleException($e->getMessage(), 0, $e);
			}
			if ($getUserSettings) {
				// TODO: merge queries for collective and user settings into one?
				$settings = $this->collectiveUserSettingsMapper->findByCollectiveAndUser($c->getId(), $userId);
				$c->setUserPageOrder(($settings ? $settings->getSetting('page_order') : null) ?? Collective::defaultPageOrder);
				$c->setUserShowMembers(($settings ? $settings->getSetting('show_members') : null) ?? Collective::defaultShowMembers);
				$c->setUserShowRecentPages(($settings ? $settings->getSetting('show_recent_pages') : null) ?? Collective::defaultShowRecentPages);
				$c->setUserFavoritePages(($settings ? $settings->getSetting('favorite_pages') : null) ?? []);
			}
		}
		return $collectives;
	}

