function findBy(IQueryBuilder $qb, ?string $userId = null, int $level = Member::LEVEL_MEMBER): ?Collective {
		try {
			$collective = $this->findEntity($qb);
			// Return any found collective if $userId is null
			if ($userId === null) {
				return $collective;
			}
			// Return member collectives with at least level `level`
