		];
		if (!$includeTrash) {
			$andX[] = $qb->expr()->isNull('trash_timestamp');
		}
		$qb->select('*')
			->from($this->tableName)
			->where($qb->expr()->andX(...$andX));
		try {
			return $this->findEntities($qb);
		} catch (Exception $e) {
