methods.OCA\\Collectives\\Search\\FileSearch\\Db:
function findDocumentsByWords(int $collectiveId, array $wordIds, int $limit): array {
		$qb = $this->db->getQueryBuilder();
		$qb->select('d.file_id')
			->selectAlias($qb->func()->sum('d.hit_count'), 'total_hits')
			->from($this->tableName, 'd')
			->innerJoin('d', 'collectives_s_words', 'w', $qb->expr()->eq('d.word_id', 'w.id'))
			->where($qb->expr()->eq('d.collective_id', $qb->createNamedParameter($collectiveId, IQueryBuilder::PARAM_INT)))
			->andWhere($qb->expr()->in('d.word_id', $qb->createNamedParameter($wordIds, IQueryBuilder::PARAM_INT_ARRAY)))
			->groupBy('d.file_id')
			->orderBy('total_hits', 'DESC')
			->setMaxResults($limit);

		$result = $qb->executeQuery();
		return $result->fetchAll();
	}

function findByCollectiveAndPrefix(int $collectiveId, string $prefix, int $limit): array {
		$qb = $this->db->getQueryBuilder();
		$qb->select('*')
			->from($this->tableName)
			->where($qb->expr()->eq('collective_id', $qb->createNamedParameter($collectiveId)))
			->andWhere($qb->expr()->like('term', $qb->createNamedParameter($prefix . '%')))
			->orderBy('num_hits', 'DESC')
			->setMaxResults($limit);

		return $this->findEntities($qb);
	}

function findByCollectiveAndTerm(int $collectiveId, string $term): ?SearchWord {
		$qb = $this->db->getQueryBuilder();
		$qb->select('*')
			->from($this->tableName)
			->where($qb->expr()->eq('collective_id', $qb->createNamedParameter($collectiveId)))
			->andWhere($qb->expr()->eq('term', $qb->createNamedParameter($term)));

		try {
			return $this->findEntity($qb);
		} catch (DoesNotExistException|MultipleObjectsReturnedException) {
			return null;
		}
	}

methods.OCA\\Collectives\\Search\\FileSearch\\Fi:
function findWordIdsForToken(int $collectiveId, string $token, array $languages, bool $isLastToken = false): array {
		// step 1: exact match
		$exactWord = $this->wordMapper->findByCollectiveAndTerm($collectiveId, $token);
		if ($exactWord !== null && !$isLastToken) {
			return ['wordIds' => [$exactWord->getId()], 'matchType' => self::MATCH_TYPE_EXACT];
		}

		// step 2: prefix match
		$prefixWords = $this->wordMapper->findByCollectiveAndPrefix($collectiveId, $token, self::TOKEN_CANDIDATE_LIMIT);
		if ($exactWord !== null || !empty($prefixWords)) {
			$wordIds = array_unique(array_map(fn ($w) => $w->getId(), $prefixWords));
			if ($exactWord !== null && !in_array($exactWord->getId(), $wordIds)) {
				$wordIds[] = $exactWord->getId();
			}
			$matchType = $exactWord !== null ? self::MATCH_TYPE_EXACT : self::MATCH_TYPE_PREFIX;
			return ['wordIds' => $wordIds, 'matchType' => $matchType];
		}

		// step 3: stem match with fuzzy fallback
		$wordIds = [];
		foreach ($languages as $language) {
			$stem = $this->stemmer->stem($token, $language);
			$stemWords = $this->wordMapper->findByCollectiveAndStem($collectiveId, $stem)
				?: $this->fuzzySearchWord($collectiveId, $token);
			foreach ($stemWords as $word) {
				$wordIds[] = $word->getId();
			}
		}
		return ['wordIds' => array_unique($wordIds), 'matchType' => self::MATCH_TYPE_STEM];
	}

function fuzzySearchWord(int $collectiveId, string $term): array {
		if (mb_strlen($term) < self::FUZZY_PREFIX_LENGTH) {
			return [];
		}

		$prefix = mb_substr($term, 0, self::FUZZY_PREFIX_LENGTH);
		$candidates = $this->wordMapper->findByCollectiveAndPrefix($collectiveId, $prefix, self::TOKEN_CANDIDATE_LIMIT);

		$matches = [];
		foreach ($candidates as $candidate) {
			$distance = levenshtein($candidate->getTerm(), $term);
			if ($distance <= self::FUZZY_MAX_DISTANCE) {
				$matches[] = $candidate;
			}
		}

		return $matches;
	}

function rankResults(array $tokenResults, array $matchingFileIds): array {
		$fileScores = [];
		$allDocs = [];

		foreach ($tokenResults as $tokenResult) {
			foreach ($tokenResult['docs'] as $doc) {
				$fileId = $doc['file_id'];
				if (!in_array($fileId, $matchingFileIds)) {
					continue;
				}
				$fileScores[$fileId] = ($fileScores[$fileId] ?? 0)
					+ $tokenResult['matchType']
					* log1p((int)$doc['total_hits']);
				$allDocs[$fileId] ??= $doc;
			}
		}

		usort($allDocs, fn ($a, $b) => ($fileScores[$b['file_id']] ?? 0) <=> ($fileScores[$a['file_id']] ?? 0));

		return array_slice($allDocs, 0, self::SEARCH_RESULT_LIMIT);
	}

function search(int $collectiveId, string $query): array {
		$languages = $this->fileMapper->getLanguagesByCollective($collectiveId) ?: [null];

		$tokens = null;
		foreach ($languages as $language) {
			$languageTokens = $this->tokenizer->tokenize($query, $language);
			$tokens = $tokens === null ? $languageTokens : array_intersect($tokens, $languageTokens);
		}
		$tokens = array_values($tokens ?? []);

		if (empty($tokens)) {
			return [];
		}

		$tokenResults = [];
		$fileIdSets = [];
		$lastIndex = array_key_last($tokens);

		foreach ($tokens as $index => $token) {
			$isLastToken = $index === $lastIndex;
			$result = $this->findWordIdsForToken($collectiveId, $token, $languages, $isLastToken);
			if (empty($result['wordIds'])) {
				return [];
			}

			$docs = $this->docMapper->findDocumentsByWords($collectiveId, $result['wordIds'], self::TOKEN_CANDIDATE_LIMIT);
			if (empty($docs)) {
				return [];
			}

			$tokenResults[] = ['matchType' => $result['matchType'], 'docs' => $docs];
			$fileIdSets[] = array_column($docs, 'file_id');
		}

		$matchingFileIds = array_intersect(...$fileIdSets);
		if (empty($matchingFileIds)) {
			return [];
		}

		return $this->rankResults($tokenResults, $matchingFileIds);
	}

methods.OCA\\Collectives\\Search\\FileSearch\\St:
function getStemmer(string $language): ?WamaniaStemmer {
		if (!array_key_exists($language, $this->stemmers)) {
			try {
				$this->stemmers[$language] = StemmerFactory::create($language);
			} catch (NotFoundException) {
				$this->stemmers[$language] = null;
			}
		}
		return $this->stemmers[$language];
	}

function stem(string $word, ?string $language = null): string {
		$language ??= $this->config->getSystemValue('default_language', 'en');
		$stemmer = $this->getStemmer($language);
		if ($stemmer === null) {
			return $word;
		}

		try {
			return $stemmer->stem($word);
		} catch (Exception) {
			return $word;
		}
	}

methods.OCA\\Collectives\\Search\\FileSearch\\To:
function getStopWords(string $language): array {
		$file = __DIR__ . '/StopWords/' . $language . '.php';
		if (file_exists($file)) {
			return require $file;
		}
		return [];
	}

function normalize(string $text): string {
		/*
		 * strip HTML tags
		 * use a regex as strip_tags() is too greedy
		 * and strips content between <!-- --> comments and other edge cases
		 */
		$text = preg_replace('/<[a-zA-Z\/][^>]*>/', '', $text) ?? $text;

		/*
		 * normalize mentions to make them searchable
		 * e.g. @[name](mention://user/name) -> @name
		 */
		$text = preg_replace('/@\[([^\]]+)\]\(mention:\/\/[^)]+\)/', '@$1', $text) ?? $text;

		return $text;
	}

function tokenize(string $text, ?string $language = null): array {
		$text = self::normalize($text);
		$text = mb_strtolower($text);
		$words = preg_split(self::PATTERN, $text, -1, PREG_SPLIT_NO_EMPTY);

		$stopwords = $language !== null ? $this->getStopWords($language) : [];
		$words = array_diff($words, $stopwords);

		return array_filter($words, function ($word) {
			$len = mb_strlen($word);
			return $len >= self::MIN_LENGTH && $len <= self::MAX_LENGTH;
		});
	}

